import { Box, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeApp } from "../types/home";

export default function AppDownload({ data }: { data?: HomeApp | null }) {
  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 10 }, backgroundColor: "#f5fafe" }}>
      <Container maxWidth="xl" sx={{ px: { xs: 2, md: 5 }, maxWidth: "90%" }}>
        <Stack direction={{ xs: "column", md: "row" }} alignItems="center" spacing={{ xs: 4, md: 0 }}>
          <Box sx={{ width: { xs: "100%", md: "40%" }, pr: { md: 4 } }}>
            <Typography sx={{ color: "#17224d", fontSize: { xs: 26, md: 35 }, fontWeight: 600, mb: 2 }}>
              {data.title}
            </Typography>
            <BlocksText content={data.description} sx={{ color: "#5a6473", fontSize: 16, mb: 3 }} />
            <Stack direction="row" spacing={2} sx={{ mb: 3 }}>
              {data.appStoreUrl && mediaUrl(data.appStoreImage) ? (
                <Box component="a" href={data.appStoreUrl} target="_blank" rel="noopener noreferrer">
                  <Box component="img" src={mediaUrl(data.appStoreImage)} alt="App Store" sx={{ height: 48 }} />
                </Box>
              ) : null}
              {data.playStoreUrl && mediaUrl(data.playStoreImage) ? (
                <Box component="a" href={data.playStoreUrl} target="_blank" rel="noopener noreferrer">
                  <Box component="img" src={mediaUrl(data.playStoreImage)} alt="Play Store" sx={{ height: 48 }} />
                </Box>
              ) : null}
            </Stack>
            {mediaUrl(data.qrImage) ? (
              <Box
                component="img"
                src={mediaUrl(data.qrImage)}
                alt="QR"
                sx={{ width: 240, height: 240, display: "block", mb: 1.5 }}
              />
            ) : null}
            <Typography sx={{ color: "#5a6473", fontSize: 16 }}>{data.qrText}</Typography>
          </Box>
          {mediaUrl(data.sideImage) ? (
            <Box
              sx={{
                width: { xs: "100%", md: "80%" },
                overflow: "hidden",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              <Box
                component="img"
                src={mediaUrl(data.sideImage)}
                alt={data.sideImage?.alternativeText || "App"}
                sx={{
                  width: "100%",
                  display: "block",
                  transformOrigin: "center",
                }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
    </Box>
  );
}
